</style>
</head>
<body>
  <div class="card">
    <h1>Table ${msg.tableNumber}</h1>
    <p>Statut : <span class="statut">${msg.commande.statut}</span></p>
    <p>Votre commande :</p>
    <ul>
      ${msg.commande.articles.map(a => `<li>${a}</li>`).join('')}
    </ul>
  </div>
</body>
