msg.payload = html;
msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
msg.statusCode = 200;

return msg;

// Prépare la requête d'agrégation MongoDB
// Récupère le token demandé dans l'URL
const token = msg.req.query.t;

if (!token) {
    msg.statusCode = 403;
    msg.payload = "<h1>Accès refusé</h1><p>Lien invalide ou expiré.</p>";
    msg.headers = { 'Content-Type': 'text/html' };
    return [null, msg]; // sort par la 2e sortie (erreur)
}

// On garde le token pour le comparer après la requête Mongo
flow.set('lookup_token', token);

msg.payload = [
    {
        $match: {
            token: token,
            statut: "ouverte"
        }
    },
    {
        $lookup: {
            from: "commandes",
            localField: "_id",
            foreignField: "visiteId",
            as: "commandes"
        }
    },
    {
        $project: {
            tableNumero: 1,
            badgeId: 1,
            clientId: 1,
            dateArrivee: 1,
            montantTotalVisite: 1,
            commandes: 1
        }
    }
];

return [msg, null];

const visite = msg.payload[0];

if (!visite) {
    msg.payload = "Aucune visite trouvée";
    return msg;
}

const commandes = visite.commandes || [];

const html = `
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Table ${visite.tableNumero}</title>

<style>
  body { 
    font-family: sans-serif; 
    background: #f4f4f4; 
    margin: 0; 
    padding: 20px; 
  }

  .card { 
    background: white; 
    border-radius: 12px; 
    padding: 20px; 
    max-width: 400px; 
    margin: 0 auto; 
    box-shadow: 0 2px 8px rgba(0,0,0,0.1); 
  }

  h1 { 
    font-size: 1.4em; 
    color: #333; 
  }

  .info {
    color: #555;
  }

  .commande {
    border-top: 1px solid #ddd;
    margin-top: 15px;
    padding-top: 10px;
  }

  .statut { 
    display: inline-block; 
    padding: 4px 12px; 
    border-radius: 20px; 
    background: #ffedcc; 
    color: #a05a00; 
    font-weight: bold; 
  }

  ul { 
    padding-left: 20px; 
  }
</style>

</head>

<body>

<div class="card">

<h1>Table ${visite.tableNumero}</h1>

<p class="info">
Arrivée : ${new Date(visite.dateArrivee).toLocaleString("fr-FR")}
</p>

<p class="info">
Total : ${visite.montantTotalVisite} €
</p>


<h2>Commandes</h2>

${commandes.length === 0 ? 
    "<p>Aucune commande</p>" 
    :
    commandes.map(cmd => `
        <div class="commande">
            <p>
                Statut :
                <span class="statut">
                    ${cmd.statut || "En attente"}
                </span>
            </p>

            <ul>
                ${(cmd.articles || []).map(article => 
                    `<li>${article}</li>`
                ).join('')}
            </ul>
        </div>
    `).join('')
}

</div>

</body>
</html>
`;

msg.payload = html;
msg.headers = {
    'Content-Type': 'text/html; charset=utf-8'
};
msg.statusCode = 200;

return msg;
